const intakeButton=document.createElement('button');intakeButton.className='btn primary';intakeButton.textContent='＋ 录入';$('.actions').prepend(intakeButton);
let batch={source:'',mode:'ai',project:'a',summary:'',task:'',stage:'draft'};
function intake(){open('录入材料','INTAKE / 人工与 Agent 协同','<p>粘贴会议材料，选择人工归类或 Agent 分析。当前页面不调用模型，不保存真实业务数据。</p><div class="editorbar"><label><input type="radio" name="intakemode" value="ai" checked> Agent 分析建议</label><label><input type="radio" name="intakemode" value="manual"> 人工选择归档</label></div><label for="intakesource">来源材料</label><textarea id="intakesource" style="width:100%;height:170px;padding:14px;border:1px solid #d4dfef;border-radius:12px" placeholder="粘贴会议记录，或使用示例体验完整流程"></textarea><div class="formrow"><label for="intakeproject">归属项目（人工可调整）</label><select id="intakeproject">'+projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')+'</select></div><div class="modalactions"><button class="btn" id="intakeexample">载入会议示例</button><button class="btn primary" id="intakenext">继续整理</button></div><p class="notice">正式版从 DSH 对话、文件与项目进入同一录入流程；指定材料才会被处理。</p>');$('#intakesource').value=batch.source;$('#intakeproject').value=batch.project;$('#intakeexample').onclick=()=>{$('#intakesource').value='联合验证方案会议：双方同意先统一评测口径。下一步整理一份评测条件清单，负责人及截止日期待定。成本测试可以考虑，尚未决定。'};$('#intakenext').onclick=()=>{batch.source=$('#intakesource').value.trim();if(!batch.source){toast('请先粘贴材料或载入示例');return}batch.mode=document.querySelector('[name=intakemode]:checked').value;batch.project=$('#intakeproject').value;batch.summary=batch.mode==='ai'?'【预设示例，非对输入内容的模型分析】\n统一评测口径；整理评测条件清单；成本测试未决定。':batch.source;batch.task=batch.mode==='ai'?'整理评测条件清单':'';reviewIntake()}}
function reviewIntake(){open('整理与归档清单','INTAKE / 草稿，可修改','<p>人工可修改所有内容。AI 模式展示固定示例，不对任意输入宣称理解。负责人和截止日未明确时保留待补。</p><div class="proof" id="intakeorigin"></div><div class="formrow"><label for="reviewproject">归档项目</label><select id="reviewproject">'+projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')+'</select></div><label for="reviewsummary">纪要 / 整理稿</label><textarea id="reviewsummary" style="width:100%;height:125px;padding:12px;border:1px solid #d3dfef;border-radius:10px"></textarea><div class="formrow"><label><input id="savetask" type="checkbox"> 同时创建待办（不执行）</label><input id="reviewtask" aria-label="行动项内容" placeholder="填写或修改行动项"></div><p>负责人：待补 · 截止日期：待补</p><label><input id="savesource" type="checkbox" checked> 保留原始材料引用</label><div class="proof">归档位置：所选项目 / 会议资料。正式版提供目录与资料库选择、同名匹配、来源引用、差异及冲突检查。</div><div class="modalactions"><button class="btn" id="intakeback">返回材料与模式</button><button class="btn primary" id="intakecommit">确认此批次 · 演示</button></div><p class="notice">对话中“按这版归档”将指向同一个草稿版本，无需再次录表单。此交互在正式接入 DSH 后实现。</p>');$('#intakeorigin').textContent='来源摘录：'+batch.source;$('#reviewproject').value=batch.project;$('#reviewsummary').value=batch.summary;$('#reviewtask').value=batch.task;$('#savetask').checked=!!batch.task;$('#intakeback').onclick=()=>{batch.summary=$('#reviewsummary').value;batch.task=$('#reviewtask').value;intake()};$('#intakecommit').onclick=()=>{const task=$('#reviewtask').value.trim();if($('#savetask').checked&&!task){toast('请填写行动项，或取消创建待办');return}batch.project=$('#reviewproject').value;batch.summary=$('#reviewsummary').value;batch.task=$('#savetask').checked?task:'';batch.stage='previewed';open('批次提交预览','RECEIPT / 未写入真实系统','<div class="proof" id="intakereceipt"></div><p>正式版按真实回执分别显示：资料已归档、待办已创建、索引中、可检索或部分失败。推测关系保持虚线。</p><p class="notice">本次仅完成交互预览，未生成文件、项目、任务、索引或长期记忆。刷新会丢失此批次。</p>');$('#intakereceipt').textContent='目标项目：'+projects.find(p=>p.id===batch.project).name+'；整理稿 1 份；待办 '+(batch.task?1:0)+' 项；执行任务 0 项。'}}
intakeButton.onclick=intake;
const inbox=document.createElement('button');inbox.textContent='收件箱';inbox.dataset.know='inbox';$('#knowtabs').prepend(inbox);const renderBeforeIntake=renderKnowledge;renderKnowledge=function(mode){if(mode!=='inbox'){renderBeforeIntake(mode);return}active('#knowtabs','know','inbox');$('#knowbody').innerHTML='<div class="surface pad"><h2>待整理材料</h2><p>人工输入与 Agent 建议汇入同一收件箱；支持待确认、冲突、失败和部分完成。</p><button class="btn primary" id="inboxnew">录入一批材料</button><p class="notice">当前无真实数据连接。示例批次仅保留在本页。</p></div>';$('#inboxnew').onclick=intake};
